from typing import List

def odd_primes_up_to(bound: int) -> List[int]:
    return [p for p in range(3, bound + 1) if all(p % d for d in range(2, int(p ** 0.5) + 1))]

def euler_pass(p: int, n: int) -> bool:
    """p does not divide n and n^((p-1)/2) = 1 (mod p); equivalent to (n/p) = +1."""
    return n % p != 0 and pow(n, (p - 1) // 2, p) == 1

def qr_feature(n: int, primes: List[int]) -> int:
    return sum(1 for p in primes if euler_pass(p, n))

def clipped_dial(n: int, level: float = -0.0035, slope: float = 0.01156, bound: int = 100) -> float:
    """Per-N sieve-yield dial, clipped at zero (needed: some N have QR = 0)."""
    q = qr_feature(n, odd_primes_up_to(bound))
    return max(0.0, level + slope * q)

if __name__ == "__main__":
    for n in [999985999949, 163520117, 2**61 - 1]:
        print(n, qr_feature(n, odd_primes_up_to(100)), clipped_dial(n))

from typing import Dict, List, Sequence

def floor_attribution(x: Sequence[int], y: Sequence[float], a: float, b: float) -> Dict[str, float]:
    """Pure-error floor of feature-only predictors and the lack-of-fit of the
    affine dial a + b*x:  SSE(a,b) = PE + sum (m(x_i) - a - b x_i)^2."""
    groups: Dict[int, List[float]] = {}
    for xi, yi in zip(x, y):
        groups.setdefault(xi, []).append(yi)
    m = {k: sum(v) / len(v) for k, v in groups.items()}
    pe = sum((yi - m[xi]) ** 2 for xi, yi in zip(x, y))
    sse = sum((yi - a - b * xi) ** 2 for xi, yi in zip(x, y))
    lof = sum((m[xi] - a - b * xi) ** 2 for xi in x)
    return {"pure_error": pe, "sse": sse, "lack_of_fit": lof,
            "ratio": sse / pe if pe > 0 else float("inf"), "identity_residual": sse - pe - lof}

if __name__ == "__main__":
    import random
    rng = random.Random(3)
    xs = [sum(rng.random() < 0.47 for _ in range(24)) for _ in range(1000)]
    ys = [-0.0035 + 0.01156 * q + rng.gauss(0, 0.02) for q in xs]
    print(floor_attribution(xs, ys, -0.0035, 0.01156))
